"use strict";

function renderHealth(){
  const r=routeInfo();
  const service=r.params.get("service");
  const healthGroup=D.serviceGroups.find(x=>x.key==="health");
  const temporary=D.listings.filter(x=>x.group==="health"&&(!service||publicSubcategory(x.subcategory)===service));
  const providerCards=D.healthProviders.map(h=>{
    const example=h.status==="prototype-only";
    return `<article class="result-card"><div><span class="owner-label">${example?"Пример за интерфейса":"Проверен здравен запис"}</span><h3>${esc(h.name)}</h3><p>${esc(h.specialty)}</p><div class="result-meta"><span class="badge ${example?"badge-blue":"badge-ok"}">${example?"Примерен запис":"Потвърдено"}</span><span>${esc(h.kind)}</span><span>${esc(h.address)}</span></div></div><div class="result-actions"><button class="button button-primary" type="button" data-action="call" data-phone="${esc(h.phone)}">Обади се</button><button class="button button-soft" type="button" data-route="health-provider/${h.id}">Информация</button></div></article>`;
  }).join("");
  main.innerHTML=pageIntro("Услуги → Здраве и грижа","Здраве и грижа","Един публичен здравен вход с два ясно различни типа съдържание: проверени специалисти и практики, и временни здравни услуги.",button("Добави специалист или практика","health-proposal","button button-primary")+button("Публикувай или потърси здравна услуга",`listing-form?main=services&group=health${service?`&leaf=${encodeURIComponent(service)}`:""}`))+`<section class="section"><div class="shell">${crumb([["Обяви и услуги","marketplace"],["Услуги","marketplace/services"],["Здраве и грижа",""]])}<div class="health-dual"><div class="health-panel"><span class="badge badge-ok">Специалисти и практики</span><h2>Проверена здравна информация</h2><p>Тези профили са отделни от обявите и се публикуват само след проверка.</p><div class="notice notice-info mt-12"><strong>Офлайн прототип</strong>Реалният списък идва от публикуваните проверени здравни записи. Картите по-долу са примери за преглед на интерфейса и не твърдят, че показват реални лица или практики.</div><div class="result-list mt-16">${providerCards}</div><div class="mt-12">${button("Добави специалист или практика","health-proposal","button button-primary")}</div></div><div class="health-panel"><span class="badge badge-blue">Обяви за услуги</span><h2>Здравни услуги</h2><p>Временни предложения и търсения. Една такава обява не получава автоматично статус „проверен специалист“.</p><div class="health-services">${healthGroup.leaves.map(l=>`<button class="health-service" type="button" data-route="marketplace/services?group=health&service=${encodeURIComponent(l)}">${esc(l)}</button>`).join("")}</div></div></div>${service?`<div class="divider"></div>${listingBrowse({title:service,text:"Временни предложения и търсения за избраната здравна услуга.",rows:temporary,baseRoute:`marketplace/services?group=health&service=${encodeURIComponent(service)}`})}`:""}<div class="notice notice-info mt-16"><strong>Ясна граница на доверие</strong>Провереният здравен профил и временната обява могат да са на една публична страница, но остават отделни записи с различно значение.</div></div></section>`;
}

function renderHealthProvider(id){
  const h=D.healthProviders.find(x=>x.id===id);
  if(!h)return renderNotFound();
  const example=h.status==="prototype-only";
  const shareAction=example?`<button class="button button-outline" type="button" disabled>Споделяне само за публикуван запис</button>`:`<button class="button button-outline" type="button" data-share="health-provider/${h.id}" data-share-title="${esc(h.name)}">Сподели</button>`;
  main.innerHTML=pageIntro("Здраве и грижа",h.name,h.specialty,`<button class="button button-primary" type="button" data-action="call" data-phone="${esc(h.phone)}">Обади се</button>`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main">${crumb([["Услуги","marketplace/services"],["Здраве и грижа","marketplace/services?group=health"],[h.name,""]])}<div class="detail-block ${example?"":"trust-strip"}"><strong>${example?"Примерен запис за преглед на интерфейса":"Проверена здравна информация"}</strong><br>${esc(h.confirmed)}${h.source?` · ${esc(h.source)}`:""}</div><div class="detail-block"><h2>Информация</h2><div class="facts"><div class="fact"><span>Тип</span><strong>${esc(h.kind)}</strong></div><div class="fact"><span>Специалност</span><strong>${esc(h.specialty)}</strong></div><div class="fact"><span>Адрес</span><strong>${esc(h.address)}</strong></div><div class="fact"><span>Телефон</span><strong>${esc(h.phone)}</strong></div></div></div></div><aside class="detail-side"><div class="detail-block detail-actions"><button class="button button-primary" type="button" data-action="call" data-phone="${esc(h.phone)}">Обади се</button>${example?"":`<button class="button button-outline" type="button" data-route="correction?target=${encodeURIComponent(h.name)}&owner=health">Предложи корекция</button>`}${shareAction}</div></aside></div></section>`;
}

function renderHealthProposal(){
  main.innerHTML=pageIntro("Здраве и грижа","Добави специалист или практика","Специализирано предложение за проверка. Това не е фирмена форма и не е временна обява.")+`<section class="section"><div class="shell form-wrap"><div class="form-card"><div class="notice notice-info"><strong>Публикуване след проверка</strong>Предложението няма да се покаже публично, докато не бъде проверено и одобрено.</div><form class="form-grid proto-form mt-16" data-form="health-proposal"><fieldset class="field field-full"><legend>Тип</legend><div class="choice-grid"><div class="choice"><input id="hp-doctor" name="type" type="radio" value="Лекар" required checked><label for="hp-doctor"><strong>Лекар</strong><small>Специалист или личен лекар</small></label></div><div class="choice"><input id="hp-dentist" name="type" type="radio" value="Стоматолог"><label for="hp-dentist"><strong>Стоматолог</strong><small>Дентална практика</small></label></div><div class="choice"><input id="hp-vet" name="type" type="radio" value="Ветеринар"><label for="hp-vet"><strong>Ветеринар</strong><small>Ветеринарен специалист или кабинет</small></label></div></div></fieldset>${field("Име","name",{required:true,min:3,placeholder:"Име на специалиста или практиката"})}${field("Специалност","specialty",{required:true,min:3})}${field("Телефон","phone",{required:true,type:"tel",placeholder:"0... или +359..."})}${field("Адрес","address",{required:true,min:3})}${field("Допълнителна информация","notes",{textarea:true,full:true,required:true,min:20})}<label class="check-row field-full"><input type="checkbox" name="consent" required> Потвърждавам, че подавам информация за проверка и разбирам, че тя няма да се публикува автоматично.</label><div class="form-actions"><button class="button button-outline" type="button" data-route="marketplace/services?group=health">Отказ</button><button class="button button-primary" type="submit">Изпрати за проверка</button></div></form></div></div></section>`;
  bindFormUX();
}

function renderListingDetail(id){
  const l=D.listings.find(x=>x.id===id);
  if(!l)return renderNotFound();
  const shareAllowed=l.status==="approved";
  const ownedByCurrentUser=signedIn()&&D.profile.listings.some(x=>x.title===l.title);
  const protectedAdminOwned=isAdmin()&&Boolean(l.admin);
  const canEdit=ownedByCurrentUser||protectedAdminOwned;
  main.innerHTML=pageIntro("Обява",l.title,`${l.type} · ${l.category}`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main">${crumb([["Обяви и услуги","marketplace"],[l.title,""]])}<div class="detail-title"><div class="flex">${statusBadge(l.status)}${l.ownerType==="firm"?`<span class="badge badge-blue">Фирмена обява</span>`:""}</div><h1>${esc(l.title)}</h1><p>${esc(l.description)}</p><div class="tag-row"><span class="badge">${esc(l.type)}</span><span class="badge">${esc(l.city)}</span>${l.subcategory?`<span class="badge">${esc(publicSubcategory(l.subcategory))}</span>`:""}</div></div><div class="detail-block"><h2>Описание</h2><p>${esc(l.description)}</p></div><div class="detail-block"><h2>Снимки</h2><div class="photo-preview">${Array.from({length:Math.max(1,l.photos||0)},(_,i)=>`<span>${l.photos?`Снимка ${i+1}`:"Няма снимки"}</span>`).join("")}</div></div>${l.status!=="approved"?`<div class="notice notice-warn"><strong>Тази публикация не е публична</strong>Споделянето е недостъпно, докато обявата не бъде одобрена и публикувана.</div>`:""}</div><aside class="detail-side"><div class="detail-block detail-actions"><div class="price mb-0">${esc(l.price||"Цена не е посочена")}</div><button class="button button-primary" type="button" data-action="call" data-phone="${esc(l.phone)}">Покажи / позвъни</button>${shareAllowed?`<button class="button button-outline" type="button" data-share="listing/${l.id}" data-share-title="${esc(l.title)}">Сподели</button>`:`<button class="button button-outline" type="button" disabled title="Достъпно след одобрение">Сподели след одобрение</button>`}<button class="button button-outline" type="button" data-route="report?target=${encodeURIComponent(l.title)}&owner=listing">Докладвай</button>${canEdit?`<button class="button button-soft" type="button" data-route="listing-form?edit=${l.id}">Редактирай</button>`:""}</div><div class="detail-block"><h2>Публикувано от</h2><p class="mt-0"><strong>${esc(l.owner)}</strong><br><span class="muted">${l.ownerType==="firm"?"Одобрена фирма":"Лична обява"}</span></p></div></aside></div></section>`;
}

function field(label,name,o={}){
  const type=o.type||"text",id=`f-${name}`;
  return `<div class="field ${o.full?"field-full":""}" data-field="${esc(name)}"><label for="${id}">${esc(label)}${o.required?" *":""}</label>${o.textarea?`<textarea id="${id}" name="${esc(name)}" ${o.required?"required":""} ${o.min?`minlength="${o.min}"`:""} ${o.max?`maxlength="${o.max}"`:""} placeholder="${esc(o.placeholder||"")}">${esc(o.value||"")}</textarea>`:`<input id="${id}" name="${esc(name)}" type="${esc(type)}" ${o.required?"required":""} ${o.min?`minlength="${o.min}"`:""} ${o.max?`maxlength="${o.max}"`:""} ${o.minNum!=null?`min="${o.minNum}"`:""} value="${esc(o.value||"")}" placeholder="${esc(o.placeholder||"")}" autocomplete="${esc(o.autocomplete||"off")}">`}${o.help?`<small>${esc(o.help)}</small>`:""}<small class="field-error" data-error-for="${esc(name)}" aria-live="polite"></small></div>`;
}

function selectField(label,name,options,value="",o={}){
  return `<div class="field ${o.full?"field-full":""}" data-field="${esc(name)}"><label for="f-${esc(name)}">${esc(label)}${o.required?" *":""}</label><select id="f-${esc(name)}" name="${esc(name)}" ${o.required?"required":""}><option value="">${esc(o.placeholder||"Избери")}</option>${options.map(x=>{const v=typeof x==="string"?x:x.value,lab=typeof x==="string"?x:x.label;return `<option value="${esc(v)}" ${String(value)===String(v)?"selected":""}>${esc(lab)}</option>`}).join("")}</select><small class="field-error" data-error-for="${esc(name)}" aria-live="polite"></small></div>`;
}

function listingPublicMain(value){
  return ({services:"Услуги",vehicles:"Автомобили",work:"Работа",property:"Имоти",trade:"Купува и продава"})[value]||value;
}
